INSERT INTO `comments` VALUES (1,1,5,NULL,5,'Thịt bò xào lửa lớn đúng như mẹo của đầu bếp, mềm ngọt mọng nước và không hề bị dai chút nào!',NULL,'2026-10-27 08:12:29',0,0),(2,1,6,NULL,5,'Hành tây và cần tây xào chín tới giòn ngọt, thơm nức mũi. Cả nhà mình ai cũng thích!',NULL,'2026-10-29 08:12:29',0,0),(3,55,8,NULL,5,'Đánh trứng sủi bọt rán lửa vừa nở xốp mềm béo ngậy, sốt cà chua chua ngọt rất vừa vặn.',NULL,'2026-10-28 08:12:29',0,0),(4,55,4,NULL,5,'Món này làm nhanh trong 10 phút là xong bữa tối, ăn với cơm nóng thì tuyệt vời.',NULL,'2026-10-30 08:12:29',0,0),(5,36,5,NULL,5,'Nước dùng ninh xương bò trong veo và thơm ngát mùi hồi quế đúng điệu phố cổ cô Hoa ơi! Cả nhà cháu ăn ai cũng tấm tắc khen ngon.',NULL,'2026-10-25 08:12:29',0,0),(6,36,7,NULL,5,'Công thức nấu nước dùng chuẩn chỉ lắm. Mình cho thêm 1 thìa nước mắm ngon lúc chuẩn bị múc ra bát, mùi thơm bốc lên nức nở khắp cả gian bếp.',NULL,'2026-10-26 08:12:29',0,0),(7,19,2,NULL,5,'Tô canh chua miền Tây đúng điệu giải nhiệt ngày oi bức. Thịt cá lóc đồng ngọt thơm, vị chua thanh từ me chín cực kỳ thanh mát.',NULL,'2026-10-28 08:12:29',0,0),(8,37,9,NULL,5,'Kho nước dừa liu riu miếng mỡ trong veo, thịt mềm tan béo ngậy mà không hề ngấy.',NULL,'2026-10-29 08:12:29',0,0),(10,39,4,NULL,5,'Tỷ lệ pha nước sốt chuẩn 10 điểm, sườn mềm ngấm sốt nâu bóng bám quanh từng miếng thịt.',NULL,'2026-10-31 08:12:29',0,0),(11,60,1,NULL,5,'ngon quá',NULL,'2026-11-01 08:44:58',0,0),(12,60,1,NULL,3,'không ngon',NULL,'2026-11-01 19:50:32',0,0),(13,60,4,NULL,1,'Món ăn nấu dở ẹc, đồ lừa đảo mất dạy không ăn được!',NULL,'2026-11-01 20:11:36',1,1);
